import type { ScryfallCard } from '@/types/scryfall';
import { getOracleId } from '@/utils/cards';

/**
 * The real Scryfall data behind the mock seed (generated by `npm run seed:cards`).
 * Loaded with require() so TypeScript doesn't infer a type for the whole JSON file.
 */
const data = require('./cards.json') as { cards: ScryfallCard[] };

const cards: readonly ScryfallCard[] = data.cards;
const byId = new Map(cards.map((card) => [card.id, card]));
const byOracle = new Map(cards.map((card) => [getOracleId(card), card]));
const byName = new Map<string, ScryfallCard>();
for (const card of cards) {
  byName.set(card.name.toLowerCase(), card);
  // Double-faced cards are also findable by their front-face name.
  for (const face of card.card_faces ?? []) {
    const key = face.name.toLowerCase();
    if (!byName.has(key)) byName.set(key, card);
  }
}

export const catalog = {
  all: cards,
  byId: (id: string) => byId.get(id),
  byOracle: (oracleId: string) => byOracle.get(oracleId),
  byName: (name: string) => byName.get(name.toLowerCase()),

  /** For seed data: a missing name means cards.json is stale. */
  require(name: string): ScryfallCard {
    const card = byName.get(name.toLowerCase());
    if (!card) throw new Error(`"${name}" is not in src/data/mock/cards.json — run \`npm run seed:cards\`.`);
    return card;
  },

  /** Offline stand-in for Scryfall autocomplete. */
  searchNames(query: string, limit = 20): string[] {
    const q = query.trim().toLowerCase();
    if (q.length < 2) return [];
    return cards
      .filter((card) => card.name.toLowerCase().includes(q))
      .sort((a, b) => Number(!a.name.toLowerCase().startsWith(q)) - Number(!b.name.toLowerCase().startsWith(q)))
      .slice(0, limit)
      .map((card) => card.name);
  },
};
